const fs = require('fs');
const vm = require('vm');
const RealDate = Date;
class MockDate extends RealDate {
  constructor(...args) { super(...(args.length ? args : ['2026-04-28T09:00:00+07:00'])); }
  static now() { return new RealDate('2026-04-28T09:00:00+07:00').getTime(); }
  static parse(value) { return RealDate.parse(value); }
  static UTC(...args) { return RealDate.UTC(...args); }
}
MockDate.prototype = RealDate.prototype;

const index = fs.readFileSync('index.html', 'utf8');
const script = index.match(/<script>([\s\S]*?)<\/script>\s*<\/body>/i)[1];
const helpers = script.match(/function escapeHtml[\s\S]*?\n  function renderRecruitmentEmpty/)[0].replace(/\n  function renderRecruitmentEmpty$/, '');
const context = { Date: MockDate, Number, Math, String, JSON, Array, window: {} };
vm.createContext(context);
vm.runInContext(helpers, context);
const rawJson = index.match(/<!-- HOME_RECRUITMENT_FALLBACK_START -->([\s\S]*?)<!-- HOME_RECRUITMENT_FALLBACK_END -->/)[1].trim();
const jobs = JSON.parse(rawJson);
const host = { innerHTML: '' };
context.renderRecruitmentCards(host, jobs);
const labels = [...host.innerHTML.matchAll(/<span>(Đã đăng[^<]+|Mới đăng[^<]+)<\/span>/g)].map(m => m[1]);
console.log('index simulated posted labels:', labels.length, [...new Set(labels)].join(' | '));
if (labels.length !== 3 || labels.some(label => label !== 'Đã đăng 2 tuần')) {
  throw new Error('index posted label simulation failed: ' + JSON.stringify(labels));
}
if ((host.innerHTML.match(/class="job-card-posted"/g) || []).length !== 3) {
  throw new Error('index job-card-posted markup count mismatch');
}

const tuyen = fs.readFileSync('tuyen-dung.html', 'utf8');
const helperBlock = tuyen.match(/function getPublishAgeInDays[\s\S]*?\n\s*function initJobsFilter/)[0].replace(/\n\s*function initJobsFilter$/, '');
const appended = [];
const fakeSpan = { textContent: '' };
const fakePosted = { className: '', title: '', _html: '', querySelector(sel) { return sel === 'span' ? fakeSpan : null; } };
Object.defineProperty(fakePosted, 'innerHTML', { set(value) { this._html = value; }, get() { return this._html; } });
const fakeMain = { appendChild(node) { appended.push({ node, text: fakeSpan.textContent }); } };
const fakeCard = {
  dataset: { publishDate: '2026-04-09' },
  querySelector(sel) {
    if (sel === '.job-card-posted') return null;
    if (sel === '.job-card-main') return fakeMain;
    return null;
  }
};
const context2 = { Date: MockDate, Number, Math, String, document: { createElement(tag) { if (tag !== 'div') throw new Error('unexpected tag'); return fakePosted; } } };
vm.createContext(context2);
vm.runInContext(helperBlock, context2);
context2.hydrateJobPostedLabels([fakeCard]);
console.log('tuyen hydration label:', appended[0] && appended[0].text, 'title:', appended[0] && appended[0].node.title);
if (appended.length !== 1 || appended[0].text !== 'Đã đăng 2 tuần' || appended[0].node.title !== 'Ngày đăng: 09/04/2026') {
  throw new Error('tuyen hydration simulation failed');
}
const publishCount = (tuyen.match(/data-publish-date=/g) || []).length;
console.log('tuyen static publish dates:', publishCount);
if (publishCount !== 18) throw new Error('unexpected publish date count');
