from pathlib import Path
import re, html, unicodedata, collections
text=Path('tuyen-dung.html').read_text(encoding='utf-8')
def norm(s):
    s=''.join(c for c in unicodedata.normalize('NFD', s.lower()) if unicodedata.category(c)!='Mn')
    return s.replace('đ','d')
role_options=set(re.findall(r'<option value="([^"]+)">[^<]+</option>', text[text.find('id="jobsFilterRole"'):text.find('</select>', text.find('id="jobsFilterRole"'))])); role_options.discard('')
loc_options=set(re.findall(r'<option value="([^"]+)">[^<]+</option>', text[text.find('id="jobsFilterLocation"'):text.find('</select>', text.find('id="jobsFilterLocation"'))])); loc_options.discard('')
exp_options=set(re.findall(r'<option value="([^"]+)">[^<]+</option>', text[text.find('id="jobsFilterExperience"'):text.find('</select>', text.find('id="jobsFilterExperience"'))])); exp_options.discard('')
card_attrs=re.findall(r'<article class="job-card"([^>]*)>', text)
role=collections.Counter(); loc=collections.Counter(); exp=collections.Counter(); searches=[]
for attrs in card_attrs:
    def attr(k):
        m=re.search(k+r'="([^"]*)"', attrs); return html.unescape(m.group(1)) if m else ''
    role[attr('data-role-group')]+=1; loc[attr('data-location-group')]+=1; exp[attr('data-experience')]+=1; searches.append(attr('data-search'))
issues=[]; positive=[]
for m in re.finditer(r'<a[^>]+data-jobs-directory-filter="([^"]+)"([^>]*)>\s*<span class="jobs-directory-text">([^<]+)</span><span class="jobs-directory-count">([^<]+)</span>', text):
    kind, attrs, label, shown = m.group(1), m.group(2), html.unescape(m.group(3)), html.unescape(m.group(4))
    val=re.search(r'data-filter-value="([^"]+)"', attrs)
    term=re.search(r'data-search-term="([^"]+)"', attrs)
    if kind=='role':
        if not val or val.group(1) not in role_options: issues.append((kind,label,'bad value'))
        count=role[val.group(1)]
    elif kind=='location':
        if not val or val.group(1) not in loc_options: issues.append((kind,label,'bad value'))
        count=loc[val.group(1)]
    elif kind=='experience':
        if not val or val.group(1) not in exp_options: issues.append((kind,label,'bad value'))
        count=exp[val.group(1)]
    elif kind=='search':
        if not term: issues.append((kind,label,'missing term')); count=0
        else:
            nt=norm(term.group(1)); count=sum(1 for s in searches if nt in s)
    else:
        continue
    expected = f'{count} việc' if count else 'Sắp có'
    if shown != expected: issues.append((kind,label,shown,expected))
    if count: positive.append((kind,label,count))
print('cards:', len(card_attrs), 'positive directory links:', len(positive), 'issues:', issues)
print('first positives:', positive[:12])
parts=[]
for m in re.finditer(r'<script\b([^>]*)>(.*?)</script>', text, re.S|re.I):
    attrs=m.group(1)
    if re.search(r'\bsrc\s*=', attrs, re.I): continue
    parts.append(m.group(2))
out=Path('.m/verify-directory-final.inline.js')
out.write_text('\n;\n'.join(parts), encoding='utf-8')
print('inline script bytes:', out.stat().st_size)
if issues: raise SystemExit(1)
